// science.viewer.well_log_plan — Qt-free parity tests for the well-log
// C++ migration slices:
//   1. adapter replay: libs/visualization well_log_document_plan must
//      reproduce the REAL Python adapter's parity_snapshot for every frozen
//      oracle case (fixture generated by generate_oracle.py from
//      paleo_workbench/viz/welllog_engine_adapter.py).
//   2. negative self-check: the oracle's deliberately wrong-namespace id must
//      NOT match the C++ encoder (proves the comparator can fail).
//   3. track layout model: Python well_log_track_layout.py semantics
//      (merge cap, GR-guaranteed default, reconcile) + template JSON
//      round-trip and rejection paths.

#include "../pwb_test.hpp"

#include <pwb/viz/well_log_document_plan.hpp>
#include <pwb/viz/well_log_track_layout.hpp>

#include <nlohmann/json.hpp>

#include <cmath>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

using namespace pwb::viz;

namespace {

double f64_decode(const nlohmann::json& value) {
    if (value.is_string()) {
        const auto text = value.get<std::string>();
        if (text == "NaN") return std::nan("");
        if (text == "Infinity") return HUGE_VAL;
        if (text == "-Infinity") return -HUGE_VAL;
    }
    return value.get<double>();
}

WellLogCurveInput curve_from_json(const nlohmann::json& entry) {
    WellLogCurveInput curve;
    curve.mnemonic = entry.at("mnemonic").get<std::string>();
    curve.unit = entry.at("unit").get<std::string>();
    auto depth = std::make_shared<std::vector<double>>();
    auto values = std::make_shared<std::vector<double>>();
    for (const auto& v : entry.at("depth")) depth->push_back(f64_decode(v));
    for (const auto& v : entry.at("values")) values->push_back(f64_decode(v));
    curve.depth = depth;
    curve.values = values;
    if (!entry.at("display_range").is_null()) {
        curve.display_range = std::make_pair(f64_decode(entry.at("display_range")[0]),
                                             f64_decode(entry.at("display_range")[1]));
    }
    curve.color = entry.value("color", "");
    return curve;
}

WellLogDocumentInput input_from_json(const nlohmann::json& entry) {
    WellLogDocumentInput input;
    input.well_name = entry.at("well_name").get<std::string>();
    input.top_depth = f64_decode(entry.at("top_depth"));
    input.bottom_depth = f64_decode(entry.at("bottom_depth"));
    if (!entry.at("depth_unit").is_null()) {
        input.depth_unit = entry.at("depth_unit").get<std::string>();
    }
    for (const auto& curve : entry.at("curves")) {
        input.curves.push_back(curve_from_json(curve));
    }
    for (const auto& interval : entry.value("lithology", nlohmann::json::array())) {
        input.lithology.push_back({f64_decode(interval.at("top")),
                                   f64_decode(interval.at("bottom")),
                                   interval.value("label", "")});
    }
    for (const auto& interval : entry.value("facies", nlohmann::json::array())) {
        input.facies.push_back({f64_decode(interval.at("top")),
                                f64_decode(interval.at("bottom")),
                                interval.value("label", "")});
    }
    if (!entry.value("facies_groups", nlohmann::json()).is_null()) {
        WellLogFaciesGroupsInput groups;
        const auto& group = entry.at("facies_groups");
        for (const auto& interval : group.value("lithology", nlohmann::json::array())) {
            groups.lithology.push_back({f64_decode(interval.at("top")),
                                        f64_decode(interval.at("bottom")),
                                        interval.value("label", "")});
        }
        for (const auto& key : {"phase", "sub_phase", "micro_phase"}) {
            for (const auto& interval : group.value(key, nlohmann::json::array())) {
                std::vector<WellLogIntervalInput>* target = key == std::string("phase")
                                                                 ? &groups.phase
                                                            : key == std::string("sub_phase")
                                                                ? &groups.sub_phase
                                                                : &groups.micro_phase;
                target->push_back({f64_decode(interval.at("top")),
                                   f64_decode(interval.at("bottom")),
                                   interval.value("label", "")});
            }
        }
        input.facies_groups = groups;
    }
    for (const auto& marker : entry.value("markers", nlohmann::json::array())) {
        WellLogMarkerInput item;
        item.depth = f64_decode(marker.at("depth"));
        item.label = marker.value("label", "");
        item.semantic = marker.value("semantic", "");
        item.id = marker.value("id", "");
        input.markers.push_back(item);
    }
    return input;
}

// Structural comparison with exact float equality: the C++ port consumes the
// same IEEE-754 inputs and performs no floating point arithmetic beyond
// comparisons, so bit-identical outputs are the bar.
void compare_snapshot(const nlohmann::json& expected,
                      const nlohmann::json& actual, const std::string& context) {
    const auto fail = [&context, &expected, &actual](const std::string& what) {
        std::cerr << "EXPECTED: " << expected.dump() << "\n";
        std::cerr << "ACTUAL:   " << actual.dump() << "\n";
        PWB_FAIL((context + ": " + what).c_str());
    };
    if (expected["well_name"] != actual["well_name"]) fail("well_name");
    if (expected["top_depth"] != actual["top_depth"]) fail("top_depth");
    if (expected["bottom_depth"] != actual["bottom_depth"]) fail("bottom_depth");
    if (expected["document_id"] != actual["document_id"]) fail("document_id");

    const auto& expected_curves = expected["curves"];
    const auto& actual_curves = actual["curves"];
    if (expected_curves.size() != actual_curves.size()) fail("curve count");
    for (std::size_t i = 0; i < expected_curves.size() && i < actual_curves.size();
         ++i) {
        const auto& e = expected_curves[i];
        const auto& a = actual_curves[i];
        for (const char* key : {"mnemonic", "unit", "depth_unit", "length",
                                "depth_first", "depth_last", "value_first",
                                "value_last", "curve_id", "axis_id"}) {
            if (e[key] != a[key]) fail(std::string("curve ") +
                                       std::to_string(i) + " field " + key);
        }
        if (bool(e["depth_unit_declared"]) != bool(a["depth_unit_declared"])) {
            fail("depth_unit_declared");
        }
        if (e["null_indices"] != a["null_indices"]) {
            fail("null_indices");
        }
    }
    if (expected["lithology_bounds"] != actual["lithology_bounds"]) {
        fail("lithology_bounds");
    }
    if (expected["facies_bounds"] != actual["facies_bounds"]) fail("facies_bounds");
    if (expected["markers"] != actual["markers"]) fail("markers");
    if (expected["diagnostics"] != actual["diagnostics"]) fail("diagnostics");
}

void compare_submit(const nlohmann::json& expected_submit,
                    const EngineLoadPlan& plan, const std::string& context) {
    const auto envelope = submit_depth_envelope(plan);
    PWB_CHECK(envelope.has_value());
    if (expected_submit["top"] != envelope->first ||
        expected_submit["bottom"] != envelope->second) {
        PWB_FAIL((context + ": submit depth envelope").c_str());
    }
    std::vector<std::string> fallbacks;
    const auto tracks = build_track_payload(plan, &fallbacks);
    // Python's plan.diagnostics at submit time = adapt diagnostics with the
    // log-scale fallbacks appended by the track payload builder.
    std::vector<std::string> diagnostics = plan.diagnostics;
    diagnostics.insert(diagnostics.end(), fallbacks.begin(), fallbacks.end());
    const auto& expected_tracks = expected_submit["tracks"];
    if (expected_tracks.size() != tracks.size()) {
        PWB_FAIL((context + ": track count " +
                  std::to_string(tracks.size()) + " != " +
                  std::to_string(expected_tracks.size()))
                     .c_str());
    }
    for (std::size_t i = 0; i < expected_tracks.size() && i < tracks.size(); ++i) {
        const auto& e = expected_tracks[i];
        const auto& a = tracks[i];
        if (e["width_mm"] != a.width_mm) PWB_FAIL((context + ": width_mm").c_str());
        const auto& layers = e["layers"];
        if (layers.empty() || a.interval_semantic.has_value()) {
            // Interval-only track: the oracle emits width/semantic/layers
            // only, no scale fields.
            if (!a.curve_id.empty()) {
                PWB_FAIL((context + ": expected interval-only track").c_str());
            }
            if (e.value("interval_semantic", "") !=
                a.interval_semantic.value_or("")) {
                PWB_FAIL((context + ": interval_semantic").c_str());
            }
            continue;
        }
        if (e.value("scale_min", 0.0) != a.scale_min) PWB_FAIL((context + ": scale_min").c_str());
        if (e.value("scale_max", 0.0) != a.scale_max) PWB_FAIL((context + ": scale_max").c_str());
        if (e.value("scale_mode", "linear") != a.scale_mode) PWB_FAIL((context + ": scale_mode").c_str());
        if (e.value("interval_semantic", "") != a.interval_semantic.value_or("")) {
            PWB_FAIL("interval_semantic");
        }
        if (layers[0]["curve_id"] != a.curve_id) PWB_FAIL("track curve_id");
        if (layers[0]["color"] != a.color) PWB_FAIL("track color");
    }
    const auto& expected_diagnostics = expected_submit["diagnostics"];
    if (expected_diagnostics.size() != diagnostics.size()) {
        PWB_FAIL((context + ": submit diagnostics count " +
                  std::to_string(diagnostics.size()) + " vs " +
                  std::to_string(expected_diagnostics.size()))
                     .c_str());
    }
    for (std::size_t i = 0;
         i < expected_diagnostics.size() && i < diagnostics.size(); ++i) {
        if (expected_diagnostics[i] != diagnostics[i]) {
            PWB_FAIL((context + ": submit diagnostic " + std::to_string(i))
                         .c_str());
        }
    }
}

std::string fixture_root() {
    const char* root = std::getenv("PWB_SCIENCE_FIXTURE_ROOT");
    return root != nullptr ? root : std::string("fixtures");
}

const nlohmann::json& oracle_fixture() {
    static nlohmann::json fixture = [&] {
        const auto path = fixture_root() + "/welllog/welllog_adapter_oracle.json";
        std::ifstream stream(path);
        if (!stream.good()) {
            PWB_FAIL("cannot open welllog_adapter_oracle.json");
        }
        try {
            nlohmann::json parsed;
            stream >> parsed;
            return parsed;
        } catch (const std::exception& e) {
            std::cerr << "fixture parse error: " << e.what() << "\n";
            PWB_FAIL("malformed oracle fixture");
        }
    }();
    return fixture;
}

} // namespace

TEST(adapter_parity_replay_against_python_oracle) {
    const auto& fixture = oracle_fixture();
    for (const auto& entry : fixture["cases"]) {
        if (entry["input"].is_null()) {
            continue; // negative self-check case handled below
        }
        const auto context = entry["name"].get<std::string>();
        const auto plan = adapt_well_log_data(input_from_json(entry["input"]));
        const auto actual = nlohmann::ordered_json::parse(parity_snapshot_json(plan));
        compare_snapshot(entry["expected"], actual, context);
        if (!entry["submit"].is_null()) {
            compare_submit(entry["submit"], plan, context);
        } else {
            // No submittable payload (empty/all-empty wells): the envelope
            // helper must refuse too.
            PWB_CHECK(!submit_depth_envelope(plan).has_value());
        }
    }
}

TEST(adapter_uuid_negative_self_check) {
    const auto& fixture = oracle_fixture();
    for (const auto& entry : fixture["cases"]) {
        if (entry["name"] != "uuid_negative_self_check") continue;
        const auto& negative = entry["negative"];
        std::vector<std::string> storage;
        for (const auto& part : negative["parts"]) {
            storage.push_back(part.get<std::string>());
        }
        const std::vector<std::string_view> parts(storage.begin(),
                                                  storage.end());
        const auto real = stable_entity_id(parts);
        PWB_CHECK_MSG(real == negative["real_id"].get<std::string>(),
                      "stable_entity_id diverges from the Python oracle");
        PWB_CHECK_MSG(real != negative["must_not_equal"].get<std::string>(),
                      "encoder must not match a foreign-namespace id");
        return;
    }
    PWB_FAIL("uuid_negative_self_check case missing from fixture");
}

TEST(track_layout_matches_python_semantics) {
    const std::vector<std::string> mnemonics = {"GR", "AC", "RT", "RXO",
                                                "DEN", "CNL", "SP", "CAL"};
    auto layout = default_track_layout(mnemonics);
    PWB_CHECK(layout.curve_count() == 8);
    // First six visible except: GR guaranteed (it is within the first six),
    // CAL (index 6) and SP... default shows exactly the first six.
    PWB_CHECK(layout.visible[0]);
    PWB_CHECK(!layout.visible[6] && !layout.visible[7]);
    // Seven curves: GR beyond the first six must replace the last shown slot.
    const std::vector<std::string> late_gr = {"AC", "RT", "RXO", "DEN", "CNL",
                                              "SP", "GR"};
    auto late_layout = default_track_layout(late_gr);
    PWB_CHECK(late_layout.visible[6]); // GR guaranteed
    PWB_CHECK(!late_layout.visible[5]); // replaced the last slot

    // curve keys are index-based, duplicate-safe.
    const std::vector<std::string> dup = {"GR", "GR"};
    auto dup_layout = default_track_layout(dup);
    PWB_CHECK(dup_layout.curve_keys[0] != dup_layout.curve_keys[1]);
    PWB_CHECK(dup_layout.curve_keys[0] == curve_key_for(0, "GR"));

    // Visibility toggles round-trip.
    auto toggled = layout.with_visible("curve:0:GR", false)
                       .with_visible("curve:6:SP", true);
    PWB_CHECK(!toggled.visible[0] && toggled.visible[6]);

    // Merge: dragging SP onto RT renames the group header order to SP / RT.
    auto merged = toggled.merge("curve:6:SP", "curve:2:RT");
    const auto& group = merged.group_for("curve:6:SP");
    PWB_CHECK(group.size() == 2 && group.front() == "curve:6:SP");
    // Merge cap: three curves per track.
    auto full = merged.merge("curve:3:RXO", "curve:2:RT");
    PWB_CHECK(full.group_for("curve:2:RT").size() == 3);
    bool raised = false;
    try {
        (void)full.merge("curve:1:AC", "curve:2:RT");
    } catch (const curve_group_limit_error&) {
        raised = true;
    }
    PWB_CHECK(raised);
    // Unmerge restores one track per curve.
    auto split = full.unmerge("curve:2:RT");
    PWB_CHECK(split.group_for("curve:2:RT").size() == 1);
    PWB_CHECK(split.group_for("curve:6:SP").size() == 1);

    // Unknown keys throw (Python KeyError).
    raised = false;
    try {
        (void)layout.with_visible("curve:99:NOPE", true);
    } catch (const std::out_of_range&) {
        raised = true;
    }
    PWB_CHECK(raised);

    // Reorder moves whole groups.
    auto moved = layout.move_group("curve:3:RXO", 0);
    PWB_CHECK(moved.groups.front().front() == "curve:3:RXO");

    // Scale mode + color overrides.
    auto styled = layout.with_scale_mode("curve:0:GR", TrackScaleMode::logarithmic)
                      .with_color("curve:0:GR", "#ff8800");
    PWB_CHECK(styled.scale_mode[0] == TrackScaleMode::logarithmic);
    PWB_CHECK(styled.color[0] == "#ff8800");
}

TEST(track_layout_template_json_round_trip) {
    const std::vector<std::string> mnemonics = {"GR", "AC", "RT"};
    auto layout = default_track_layout(mnemonics)
                      .with_visible("curve:1:AC", false)
                      .with_scale_mode("curve:2:RT", TrackScaleMode::logarithmic)
                      .with_color("curve:0:GR", "#112233")
                      .merge("curve:2:RT", "curve:0:GR");
    const auto json_text = layout.to_template_json();

    WellLogTrackLayout parsed;
    std::string error;
    PWB_CHECK_MSG(WellLogTrackLayout::from_template_json(json_text, parsed, &error),
                  error.c_str());
    PWB_CHECK(parsed.curve_keys == layout.curve_keys);
    PWB_CHECK(parsed.visible == layout.visible);
    PWB_CHECK(parsed.groups == layout.groups);
    PWB_CHECK(parsed.scale_mode[2] == TrackScaleMode::logarithmic);
    PWB_CHECK(parsed.color[0] == "#112233");
    PWB_CHECK(parsed.to_template_json() == json_text); // deterministic

    // Rejection paths: not the template schema, malformed JSON, groups that do
    // not cover the curves.
    PWB_CHECK(!WellLogTrackLayout::from_template_json("{}", parsed, &error));
    PWB_CHECK(!WellLogTrackLayout::from_template_json("{broken", parsed, &error));
    const std::string bad_groups =
        R"({"schema":"pwb.well_log_track_template","version":1,)"
        R"("curves":[{"key":"curve:0:GR","visible":true,"scale_mode":"auto","color":""}],)"
        R"("groups":[]})";
    PWB_CHECK(!WellLogTrackLayout::from_template_json(bad_groups, parsed, &error));
}

TEST(track_layout_reconcile_drops_stale_schema) {
    const std::vector<std::string> first = {"GR", "AC"};
    auto layout = default_track_layout(first);
    // Same schema → kept.
    PWB_CHECK(reconcile_track_layout(layout, first).curve_keys == layout.curve_keys);
    // New well with different curves → fresh default.
    const std::vector<std::string> second = {"RT"};
    auto reconciled = reconcile_track_layout(layout, second);
    PWB_CHECK(reconciled.curve_keys.size() == 1);
    PWB_CHECK(reconciled.visible[0]);
}

